-- Topic: Misstatements and Control Deficiencies
-- Difficulty: 9E / 15M / 6H
-- Bloom's: L1:8 / L2:9 / L3:8 / L4:5

BEGIN;

INSERT INTO questions (section_id, topic, stem, choices, correct_index, explanation, difficulty, cognitive_level)
VALUES

-- Q1: easy / L3 — Clearly trivial threshold effect on accumulation
(1, 'Misstatements and Control Deficiencies', 'During the audit of Birchfield Enterprises, the engagement team identifies a $200 classification error in office supplies. The auditor''s clearly trivial threshold is $5,000. What is the most likely effect of this misstatement on the audit?', '["The auditor must accumulate the misstatement and include it in the summary of uncorrected misstatements", "The auditor must communicate the misstatement to those charged with governance as a control deficiency", "The auditor need not accumulate the misstatement because it falls below the clearly trivial threshold", "The auditor must require management to correct the misstatement before issuing the audit report"]'::jsonb, 2, 'Under AU-C 450.05, the auditor need not accumulate misstatements that are clearly trivial, meaning inconsequential both individually and in aggregate. Because the $200 error is well below the $5,000 clearly trivial threshold, the auditor is not required to track it. Choice A is incorrect because accumulation is only required for misstatements that exceed the clearly trivial threshold, not for amounts of a wholly different order of magnitude than materiality.', 'easy', 3),

-- Q2: hard / L4 — Evaluating opinion type for pervasive uncorrected misstatements
(1, 'Misstatements and Control Deficiencies', 'During the audit of Granite Peak Holdings, the auditor identifies uncorrected misstatements totaling $1.8 million across revenue, inventory, and accounts payable. Overall materiality is $1.5 million. Management declines to make corrections, arguing each individual misstatement is immaterial. The misstatements affect multiple financial statement line items and include both overstatements and understatements. The auditor should:', '["Issue a qualified opinion because the misstatements are material but confined to specific accounts", "Issue an adverse opinion because the aggregate uncorrected misstatements are both material and pervasive", "Issue an unmodified opinion with an emphasis-of-matter paragraph describing the uncorrected misstatements", "Withdraw from the engagement because management has refused to cooperate with the auditor"]'::jsonb, 1, 'Under AU-C 705.08, when uncorrected misstatements are both material and pervasive to the financial statements, an adverse opinion is required. The $1.8 million aggregate exceeds $1.5 million materiality and affects multiple accounts, meeting the pervasiveness threshold. Choice A is incorrect because a qualified opinion applies only when misstatements are material but not pervasive, whereas these misstatements span revenue, inventory, and payables across multiple assertions.', 'hard', 4),

-- Q3: hard / L1 — Design deficiency definition
(1, 'Misstatements and Control Deficiencies', 'Auditing standards distinguish between two types of internal control deficiencies based on whether the issue relates to the control''s design or its operation. Under AU-C 265, a design deficiency in internal control over financial reporting exists when:', '["A control necessary to prevent or detect misstatements on a timely basis is missing, or an existing control is not properly designed to achieve its objective", "A properly designed control does not operate as intended because personnel fail to perform the control consistently", "A control operates effectively but management overrides it to misstate the financial statements intentionally", "A compensating control has not been implemented to address a previously identified weakness in the system"]'::jsonb, 0, 'Under AU-C 265.07, a design deficiency exists when a necessary control is missing or an existing control is not suitably designed to prevent or detect misstatements on a timely basis, even if operated as designed. Choice B describes an operating deficiency, not a design deficiency, because the control exists and is properly designed but personnel fail to execute it consistently.', 'hard', 1),

-- Q4: medium / L4 — Evaluating post-report discovery of material weakness
(1, 'Misstatements and Control Deficiencies', 'After issuing the audit report on Silverline Technologies'' December 31, 2025 financial statements, the engagement partner learns that a material weakness in revenue recognition existed throughout the audit period but was not identified during fieldwork. The auditor should evaluate whether to:', '["Require management to disclose the material weakness in a subsequent Form 8-K filing with the SEC", "Notify the predecessor auditor of the unidentified material weakness for inclusion in their workpapers", "Disclose the material weakness in the subsequent year''s management letter without further action on the current engagement", "Determine whether the unidentified material weakness affects the audit report and consider obligations under AU-C 585 regarding subsequently discovered facts"]'::jsonb, 3, 'Under AU-C 585, when the auditor becomes aware of facts that existed at the report date, the auditor must evaluate whether those facts might have affected the report. A missed material weakness could indicate undetected misstatements requiring report revision. Choice C is incorrect because deferring to the next year ignores the auditor''s obligation to assess the impact on the already-issued current-year report under AU-C 585.', 'medium', 4),

-- Q5: medium / L2 — Projected misstatement calculation in sampling
(1, 'Misstatements and Control Deficiencies', 'During the audit of Clearwater Distributing, the auditor selects a statistical sample of 60 accounts receivable confirmations from a population of 3,600 accounts totaling $14.4 million. The sample reveals misstatements of $12,000 across the 60 items. The projected misstatement for the accounts receivable population is:', '["$12,000 because the auditor should use only the known misstatement from the sample items tested", "$480,000 because the auditor should multiply the sample error by the total number of accounts", "$720,000 because the auditor should extrapolate the sample misstatement to the entire population proportionally", "$240,000 because the auditor should apply a 50% confidence adjustment factor to the extrapolated amount"]'::jsonb, 2, 'Under AU-C 530.13, the auditor must project misstatements found in a sample to the population. The projection is $12,000 multiplied by (3,600 / 60) = $720,000, extrapolating proportionally from the sample to the full population of accounts. Choice A is incorrect because using only the known sample misstatement without projection would understate the likely population misstatement, defeating the purpose of statistical sampling.', 'medium', 2),

-- Q6: medium / L2 — Prior-period uncorrected misstatement reversal effect
(1, 'Misstatements and Control Deficiencies', 'During the audit of Redstone Logistics for the year ended December 31, 2025, the auditor notes that $75,000 in revenue was overstated in the prior year and was not corrected. This prior-year overstatement has a reversing effect on current-year income. The auditor should:', '["Evaluate the reversing effect of the prior-year misstatement when assessing whether current-year financial statements are materially misstated", "Disregard the prior-year misstatement because it was evaluated during the prior-year audit engagement", "Require management to restate the prior-year comparative financial statements before issuing the current-year opinion", "Treat the reversing misstatement as a current-year audit adjustment and record it directly in the financial statements"]'::jsonb, 0, 'Under AU-C 450.11, when evaluating uncorrected misstatements, the auditor must consider the effect of uncorrected prior-period misstatements that have a reversing or continuing effect on the current period. The prior-year revenue overstatement reduces current-year income, requiring evaluation. Choice B is incorrect because prior-year uncorrected misstatements do not become irrelevant; their carryover effect must be reassessed in each subsequent period.', 'medium', 2),

-- Q7: easy / L2 — Identifying management bias in accounting estimates
(1, 'Misstatements and Control Deficiencies', 'During the audit of Hartwell Financial Group, the auditor observes that management consistently selects assumptions that increase reported earnings when estimating the fair value of investment securities. This pattern most likely represents:', '["A factual misstatement arising from a calculation error in the valuation model used by management", "An indicator of possible management bias in accounting estimates requiring further evaluation", "A significant deficiency in the entity''s investment valuation control process requiring written communication", "A scope limitation preventing the auditor from obtaining sufficient appropriate audit evidence"]'::jsonb, 1, 'Under AU-C 540.21, the auditor must evaluate whether assumptions used in accounting estimates indicate possible management bias. A consistent pattern of selecting assumptions that increase earnings suggests intentional bias rather than random estimation error. Choice A is incorrect because factual misstatements involve definitive errors in data or calculations, whereas systematically favorable assumption selection reflects judgment bias, not computational mistakes.', 'easy', 2),

-- Q8: medium / L3 — Corrected misstatements revealing fraud risk pattern
(1, 'Misstatements and Control Deficiencies', 'During the audit of Meridian Software Corp., the auditor identifies 14 misstatements in revenue transactions, all of which management promptly corrects. Twelve of the fourteen misstatements resulted in overstatement of revenue. The auditor should analyze the nature of these corrected misstatements because:', '["Corrected misstatements have no further audit significance once management records the adjusting entries", "The large number of misstatements requires the auditor to issue a qualified opinion regardless of correction", "Corrected misstatements must be reported to those charged with governance as material weaknesses", "A pattern of misstatements favoring revenue overstatement may indicate fraud risk or systematic control failures requiring additional procedures"]'::jsonb, 3, 'Under AU-C 450.12, even after management corrects misstatements, the auditor must consider their nature, cause, and circumstances. A directional pattern of 12 out of 14 misstatements overstating revenue suggests possible management bias or systematic control breakdowns, potentially indicating fraud risk under AU-C 240. Choice A is incorrect because corrected misstatements retain audit significance and may reveal risks requiring expanded testing or revised risk assessments.', 'medium', 3),

-- Q9: easy / L4 — Evaluating appropriateness of clearly trivial threshold
(1, 'Misstatements and Control Deficiencies', 'For the audit of Pinebrook Retail Inc., the senior auditor sets the clearly trivial threshold at $25,000. Overall materiality is $50,000. The engagement partner should assess whether this threshold is appropriate because:', '["A clearly trivial threshold set at 50% of materiality is generally too high, risking accumulation of misstatements that together could be material", "The clearly trivial threshold must always equal exactly 5% of overall materiality under AU-C 450", "Setting the clearly trivial threshold requires prior written approval from those charged with governance", "The clearly trivial threshold should be set equal to performance materiality to ensure consistency"]'::jsonb, 0, 'Under AU-C 450.A2, clearly trivial is an amount well below materiality, and setting it at 50% of materiality ($25,000 of $50,000) is generally considered too high. A threshold this close to materiality risks excluding misstatements that could aggregate to a material amount. Choice B is incorrect because AU-C 450 does not prescribe a fixed percentage; the threshold requires professional judgment, though practice typically uses a small fraction of materiality.', 'easy', 4),

-- Q10: easy / L1 — Operating deficiency definition
(1, 'Misstatements and Control Deficiencies', 'Under auditing standards, what is an operating deficiency in internal control?', '["A missing control that is necessary to meet a stated control objective", "A control that is improperly designed to prevent or detect misstatements on a timely basis", "A properly designed control that does not operate effectively in practice", "A control that has been intentionally overridden by members of management"]'::jsonb, 2, 'Under AU-C 265.07, an operating deficiency exists when a properly designed control does not operate effectively or when the person performing the control lacks the authority or competence to perform it effectively. The control exists and is properly designed but fails in execution. Choice A is incorrect because a missing control represents a design deficiency, not an operating deficiency, since the issue is the absence of a control rather than its ineffective execution.', 'easy', 1),

-- Q11: easy / L2 — Documentation of all accumulated misstatements
(1, 'Misstatements and Control Deficiencies', 'During the audit of Foxglove Catering LLC, the engagement team accumulates eight misstatements ranging from $1,200 to $4,800, all below materiality. Under AU-C 450, the auditor must document:', '["Only the misstatements that management declines to correct during the engagement", "All misstatements accumulated during the audit and whether they were corrected by management", "Only misstatements that individually exceed performance materiality for the engagement", "A summary total of all misstatements without providing individual detail for each item"]'::jsonb, 1, 'Under AU-C 450.14, the auditor must document all misstatements accumulated during the audit, including those corrected by management and those remaining uncorrected. Complete documentation enables proper evaluation of the aggregate effect on the financial statements. Choice A is incorrect because the documentation requirement applies to all accumulated misstatements, not just uncorrected ones, since corrected misstatements may reveal patterns or control issues.', 'easy', 2),

-- Q12: medium / L1 — Timing of written communication of deficiencies
(1, 'Misstatements and Control Deficiencies', 'During the audit of Cascade Valley Medical Center for the year ended December 31, 2025, the auditor identifies a significant deficiency in payroll processing controls on February 15, 2026. Under AU-C 265, the written communication of significant deficiencies and material weaknesses to those charged with governance must be made:', '["Within 30 calendar days of identifying the deficiency during fieldwork", "Before the end of the fiscal year under audit to allow timely remediation", "Immediately upon discovery during the course of audit fieldwork", "No later than 60 days following the report release date for the engagement"]'::jsonb, 3, 'Under AU-C 265.13, the auditor must communicate significant deficiencies and material weaknesses in writing to those charged with governance no later than 60 days following the report release date. This timeline allows the auditor to complete evaluation of all identified deficiencies before issuing the formal communication. Choice A is incorrect because AU-C 265 does not impose a 30-day deadline from identification; the standard ties the deadline to the report release date.', 'medium', 1),

-- Q13: hard / L3 — IT general control deficiency cascading impact
(1, 'Misstatements and Control Deficiencies', 'During the audit of Apex Global Logistics, the auditor discovers that the IT department failed to implement proper change management controls for the enterprise resource planning system during 2025. Three unauthorized program changes were made to the revenue and accounts payable modules. The auditor should analyze this finding because:', '["An IT general control deficiency affecting change management may undermine the reliability of all application controls dependent on the affected system, requiring assessment of the pervasive impact on financial reporting", "IT general control deficiencies are always classified as significant deficiencies but never as material weaknesses under AU-C 265", "The three unauthorized changes must each be treated as a separate control deficiency when evaluating the overall severity", "IT control deficiencies only affect the financial statements if they result in an actual monetary misstatement during the audit period"]'::jsonb, 0, 'Under AU-C 315.A69, IT general controls such as change management support the effective operation of application controls. When change management fails, the integrity of automated controls in affected modules becomes unreliable, potentially impacting multiple assertions across revenue and payables. Choice D is incorrect because control deficiency severity is evaluated based on the potential for misstatement, not solely on whether an actual misstatement occurred during the period.', 'hard', 3),

-- Q14: medium / L1 — Pervasive misstatement concept
(1, 'Misstatements and Control Deficiencies', 'When determining the type of modified opinion to issue, the auditor must assess whether identified misstatements are pervasive. Under AU-C 705, a misstatement is considered pervasive to the financial statements when:', '["The misstatement exceeds overall materiality by more than 50% of the established threshold", "The misstatement involves senior management or those charged with governance of the entity", "The misstatement is not confined to specific elements or accounts, represents a substantial proportion of the financial statements, or fundamentally undermines user understanding", "The misstatement was caused by fraud rather than by an unintentional accounting error"]'::jsonb, 2, 'Under AU-C 705.06, pervasive effects are those not confined to specific elements, accounts, or items, or if confined, represent a substantial proportion of the financial statements, or are fundamental to users'' understanding. Pervasiveness concerns the breadth of impact. Choice A is incorrect because exceeding materiality by a specific percentage does not determine pervasiveness; a large misstatement confined to one account may be material but not pervasive.', 'medium', 1),

-- Q15: medium / L1 — PCAOB integrated audit opinion on internal control
(1, 'Misstatements and Control Deficiencies', 'Under PCAOB Auditing Standard 2201, when performing an integrated audit of financial statements and internal control over financial reporting, the auditor is required to:', '["Report all control deficiencies including those less severe than significant deficiencies to the audit committee in writing", "Express an opinion on the effectiveness of internal control over financial reporting and identify any material weaknesses existing as of the assessment date", "Evaluate whether management''s assessment of internal control is fairly presented without independently testing controls", "Communicate all significant deficiencies in the auditor''s public report on internal control filed with the SEC"]'::jsonb, 1, 'Under PCAOB AS 2201.85, the auditor must express an opinion on the effectiveness of internal control over financial reporting and identify material weaknesses existing as of the assessment date. The opinion is based on the auditor''s own testing, not solely on management''s assessment. Choice C is incorrect because PCAOB AS 2201 requires the auditor to independently obtain evidence about internal control effectiveness, not merely evaluate management''s self-assessment.', 'medium', 1),

-- Q16: hard / L1 — Restatement as strong indicator of material weakness (PCAOB)
(1, 'Misstatements and Control Deficiencies', 'The PCAOB establishes specific indicators that suggest the existence of a material weakness in internal control over financial reporting. These indicators help auditors evaluate the severity of identified control deficiencies. Under PCAOB Auditing Standard 2201, which of the following situations creates a strong indicator that a material weakness exists?', '["The identification of a significant deficiency that has persisted for two consecutive audit periods without remediation", "The entity''s failure to maintain an internal audit function as recommended by the audit committee", "A restatement of previously issued financial statements to correct a material misstatement in those statements", "Management''s voluntary disclosure of a control deficiency in the annual report to shareholders"]'::jsonb, 2, 'Under PCAOB AS 2201.69, a restatement of previously issued financial statements to correct a material misstatement is a strong indicator, and in most cases a conclusive indicator, that a material weakness exists. The restatement demonstrates that controls failed to prevent or detect the original misstatement. Choice A is incorrect because while a recurring significant deficiency is concerning, persistence alone does not create the strong presumption of material weakness that a financial restatement does.', 'hard', 1),

-- Q17: medium / L2 — Misstatement affecting cutoff assertion
(1, 'Misstatements and Control Deficiencies', 'During the audit of Brookfield Construction Corp., the auditor discovers that $340,000 in progress billings was recorded as revenue in December 2025, although the related construction milestone was not completed until January 2026. Materiality is $500,000. This misstatement most directly affects the:', '["Cutoff assertion for revenue because the transaction was recorded in the wrong accounting period", "Existence assertion for revenue because the underlying construction project may not be real", "Completeness assertion for revenue because additional progress billings may remain unrecorded", "Valuation assertion for revenue because the contract price amount may be incorrectly stated"]'::jsonb, 0, 'Under AU-C 315.A128, the cutoff assertion addresses whether transactions are recorded in the correct accounting period. Recording revenue for a milestone not completed until January 2026 in December 2025 is a cutoff error, not an existence issue. Choice B is incorrect because the revenue and construction project exist; the misstatement concerns the timing of recognition, not whether the underlying transaction actually occurred.', 'medium', 2),

-- Q18: hard / L2 — Stratified sampling projected misstatement calculation
(1, 'Misstatements and Control Deficiencies', 'During the audit of Sentinel Insurance Group, the auditor stratifies accounts receivable into two strata. Stratum 1 (accounts over $100,000) contains 40 accounts totaling $8 million, all individually tested, with known misstatements of $45,000. Stratum 2 (accounts under $100,000) contains 2,000 accounts totaling $6 million; a sample of 80 reveals misstatements of $9,600. The total projected misstatement is:', '["$54,600 because the auditor adds the known misstatement to the sample misstatement without further projection", "$285,000 because the auditor adds the Stratum 1 known misstatement of $45,000 to the Stratum 2 projected misstatement of $240,000", "$45,000 because only Stratum 1 known misstatements are relevant when all high-value items are individually tested", "$240,000 because only the projected misstatement from the sampled stratum is relevant to the evaluation"]'::jsonb, 1, 'Under AU-C 530.13, projected misstatement combines known misstatements from 100%-tested strata with projected misstatements from sampled strata. Stratum 1 known misstatement is $45,000. Stratum 2 projection is $9,600 multiplied by (2,000 / 80) = $240,000. Total: $285,000. Choice A is incorrect because the Stratum 2 sample misstatement must be projected to the full stratum population, not simply added to the Stratum 1 known amount.', 'hard', 2),

-- Q19: medium / L3 — Qualitative factors making immaterial misstatement significant
(1, 'Misstatements and Control Deficiencies', 'During the audit of Whitmore Pharmaceuticals, the auditor discovers an uncorrected $18,000 misstatement that understates research and development expense. Overall materiality is $750,000. However, the misstatement caused the company to meet a loan covenant requiring R&D spending below a specified threshold. The auditor should analyze whether:', '["The misstatement can be disregarded because it is clearly trivial relative to overall materiality for the engagement", "The misstatement must be automatically treated as a material weakness because it relates to a loan covenant", "Qualitative factors such as the effect on loan covenant compliance make the otherwise immaterial misstatement significant to the financial statements", "The loan covenant analysis is entirely outside the scope of the financial statement audit engagement"]'::jsonb, 2, 'Under AU-C 450.11, the auditor evaluates both quantitative and qualitative factors when assessing uncorrected misstatements. Even quantitatively immaterial misstatements may be significant when they affect loan covenant compliance, trend analysis, or earnings targets. The $18,000 R&D understatement enabled covenant compliance despite being small relative to materiality. Choice A is incorrect because a misstatement affecting covenant compliance cannot be dismissed as clearly trivial regardless of its dollar amount.', 'medium', 3),

-- Q20: easy / L3 — Control deficiency effect on substantive procedures
(1, 'Misstatements and Control Deficiencies', 'During the audit of Elmwood Retail Partners, the auditor identifies a control deficiency in the purchasing approval process. What is the most likely effect on the auditor''s planned audit procedures?', '["The auditor must withdraw from the engagement due to unreliable internal controls over purchasing", "The auditor must issue a qualified opinion on the financial statements for the current period", "The auditor must report the deficiency to regulatory authorities before continuing with fieldwork", "The auditor may need to increase the extent of substantive testing for the purchasing and accounts payable cycle"]'::jsonb, 3, 'Under AU-C 330.07, when the auditor identifies control deficiencies that increase the risk of material misstatement, the auditor responds by modifying the nature, timing, or extent of substantive procedures. A purchasing approval deficiency increases risk in the expenditure cycle. Choice A is incorrect because a control deficiency does not require engagement withdrawal; the auditor adjusts the audit approach to obtain sufficient evidence through alternative substantive procedures.', 'easy', 3),

-- Q21: hard / L3 — Aggregation of factual, projected, and judgmental misstatements
(1, 'Misstatements and Control Deficiencies', 'During the audit of Atlas Marine Corp., the auditor accumulates the following uncorrected misstatements: factual misstatements of $120,000, projected misstatements from sampling of $280,000, and a judgmental misstatement of $95,000 related to the allowance for vessel repairs. Overall materiality is $600,000 and performance materiality is $450,000. The most critical consideration when evaluating these misstatements is:', '["Whether the combined effect of all three misstatement types, along with further possible misstatement from sampling, could exceed materiality when aggregated", "Whether each misstatement type individually exceeds materiality, since different misstatement types cannot be combined in the evaluation", "Whether the projected misstatement alone exceeds materiality, since projected misstatements carry the greatest inherent audit risk", "Whether the judgmental misstatement should be excluded from aggregation because accounting estimates inherently involve uncertainty"]'::jsonb, 0, 'Under AU-C 450.11, the auditor evaluates the aggregate of all uncorrected misstatements, including factual, projected, and judgmental types, plus further possible misstatement from sampling risk. Combined: $120,000 + $280,000 + $95,000 = $495,000, approaching $600,000 materiality before considering sampling risk. Choice B is incorrect because AU-C 450 requires aggregation of all misstatement types; evaluating each in isolation would understate the total likely misstatement.', 'hard', 3),

-- Q22: medium / L3 — Effect of management refusing representations about misstatements
(1, 'Misstatements and Control Deficiencies', 'During the audit of Crestline Distribution Inc., management provides written representations about the financial statements but refuses to include a representation that all known uncorrected misstatements are immaterial individually and in the aggregate. Under AU-C 580, the auditor should analyze whether this refusal:', '["Has no audit impact because the representation about the immateriality of uncorrected misstatements is optional", "Constitutes a scope limitation that may require the auditor to issue a qualified opinion or disclaimer of opinion", "Requires the auditor to independently correct all uncorrected misstatements in the financial statements", "Only affects the audit report if the uncorrected misstatements individually exceed performance materiality"]'::jsonb, 1, 'Under AU-C 580.20, if management refuses to provide a requested written representation, the auditor must evaluate whether it constitutes a scope limitation. The representation regarding uncorrected misstatements is required, and refusal raises doubt about management''s integrity and the reliability of other representations. Choice A is incorrect because AU-C 580.A22 specifically identifies the representation about uncorrected misstatements as a required element of the management representation letter.', 'medium', 3),

-- Q23: medium / L4 — Evaluating mid-year remediation of material weakness
(1, 'Misstatements and Control Deficiencies', 'During the audit of Horizon Energy Solutions for the year ended December 31, 2025, the auditor identifies that a material weakness in the cash disbursement process was remediated on September 1, 2025. The auditor must evaluate whether to:', '["Report the material weakness as fully remediated and exclude it from written communication to governance", "Classify the deficiency as a significant deficiency because it was corrected before year-end", "Assess whether the material weakness existed for a sufficient portion of the year to warrant reporting, and test the remediated control''s operating effectiveness for the remaining period", "Require management to restate all interim financial statements issued while the material weakness existed"]'::jsonb, 2, 'Under AU-C 265.A14, the auditor considers the duration and significance of a control deficiency when evaluating severity. A material weakness existing for eight months requires evaluation of its impact during that period and testing of the redesigned control''s effectiveness for the final four months. Choice A is incorrect because remediation does not eliminate the reporting obligation; the deficiency existed for most of the year, and the auditor must evaluate whether the remediated control operated effectively.', 'medium', 4),

-- Q24: medium / L1 — Form and content of written deficiency communication
(1, 'Misstatements and Control Deficiencies', 'After completing the audit and evaluating identified control deficiencies, the auditor prepares a written communication for those charged with governance. Under AU-C 265, this written communication of significant deficiencies and material weaknesses must include:', '["An assurance statement that no other control deficiencies exist beyond those identified during the audit procedures", "Specific detailed recommendations for remediation that management must implement before the next audit", "An overall opinion on the effectiveness of the entity''s internal control over financial reporting", "A description of each significant deficiency or material weakness and an explanation of its potential effects on financial reporting"]'::jsonb, 3, 'Under AU-C 265.12, the written communication must describe each significant deficiency and material weakness identified and explain its potential effects on the entity''s financial reporting. The communication provides sufficient detail for governance to understand the nature and implications. Choice C is incorrect because an AU-C 265 communication does not include an opinion on internal control effectiveness; expressing such an opinion requires an integrated audit under PCAOB AS 2201.', 'medium', 1),

-- Q25: easy / L1 — "Clearly trivial" definition
(1, 'Misstatements and Control Deficiencies', 'Under AU-C 450, what does "clearly trivial" mean when evaluating audit misstatements?', '["Amounts that are inconsequential whether individually or in the aggregate and of a wholly different smaller magnitude than materiality", "Amounts that are less than 50% of the overall materiality level established for the engagement", "Amounts that have been corrected by management during the course of the audit engagement", "Amounts that relate only to financial statement presentation and disclosure rather than account balances"]'::jsonb, 0, 'Under AU-C 450.A2, clearly trivial describes misstatements of a wholly different and smaller order of magnitude than materiality, such that they would be inconsequential whether taken individually or in the aggregate. This threshold filters out insignificant items. Choice B is incorrect because 50% of materiality is far too high for the clearly trivial threshold; clearly trivial is typically a small fraction of materiality, determined by professional judgment.', 'easy', 1),

-- Q26: medium / L2 — Magnitude/likelihood matrix for deficiency classification
(1, 'Misstatements and Control Deficiencies', 'During the audit of Pinnacle Healthcare Systems, the auditor identifies a control deficiency in the revenue cycle. The maximum potential misstatement if the control fails is $2 million, and overall materiality is $1.5 million. However, the likelihood of the control failure resulting in a misstatement is remote. The auditor should classify this deficiency as:', '["A material weakness because the potential magnitude exceeds overall materiality for the engagement", "At least a significant deficiency because the magnitude of potential misstatement exceeds materiality even though the likelihood is remote", "Not a deficiency worth reporting because the remote likelihood of misstatement makes it inconsequential", "A material weakness only if an actual misstatement was detected during the current audit period"]'::jsonb, 1, 'Under AU-C 265.A10, the severity of a control deficiency depends on both the magnitude of the potential misstatement and the likelihood of occurrence. When the potential magnitude exceeds materiality, the deficiency is at least a significant deficiency even if likelihood is remote. Choice A is incorrect because classification as a material weakness requires both material magnitude and at least a reasonable possibility of occurrence; remote likelihood does not meet that threshold.', 'medium', 2),

-- Q27: medium / L3 — Directional pattern of misstatements indicating bias
(1, 'Misstatements and Control Deficiencies', 'During the audit of Sandstone Properties LLC, the auditor accumulates five uncorrected misstatements totaling $280,000. All five overstate net income by either overstating revenue or understating expenses. Overall materiality is $400,000. The auditor should analyze whether:', '["The aggregate is acceptable because $280,000 is below the $400,000 materiality threshold for the engagement", "Each misstatement must be evaluated independently since they affect different financial statement accounts", "The consistent directional pattern increases the risk that additional undetected misstatements also overstate income, warranting further investigation", "The misstatements should be netted against any prior-year misstatement reversals before assessing materiality"]'::jsonb, 2, 'Under AU-C 450.A16, when all uncorrected misstatements move income in the same direction, the directional pattern may indicate management bias and increases the likelihood that undetected misstatements also overstate income. The auditor should consider expanding procedures or reassessing fraud risk. Choice A is incorrect because evaluating the aggregate solely on a quantitative basis ignores the qualitative significance of the directional pattern, which may indicate systematic bias.', 'medium', 3),

-- Q28: easy / L2 — Management representation letter content on misstatements
(1, 'Misstatements and Control Deficiencies', 'During the audit of Lakewood Manufacturing Inc., the auditor prepares the management representation letter for signature. Under AU-C 580, management must represent regarding uncorrected misstatements that:', '["No misstatements of any kind were identified during the course of the audit engagement", "All identified misstatements have been corrected and no outstanding adjustments remain", "The auditor''s established materiality level is appropriate for the entity''s financial statements", "The effects of uncorrected misstatements are immaterial individually and in the aggregate to the financial statements as a whole"]'::jsonb, 3, 'Under AU-C 580.A22, the management representation letter must include a representation that management believes the effects of uncorrected misstatements are immaterial, individually and in aggregate, to the financial statements as a whole. A summary of these items is typically attached to the letter. Choice A is incorrect because the representation does not state that no misstatements were found; rather, it addresses whether any uncorrected misstatements are immaterial.', 'easy', 2),

-- Q29: easy / L4 — Whether lesser deficiencies warrant communication to management
(1, 'Misstatements and Control Deficiencies', 'During the audit of Maplewood Community Credit Union, the auditor identifies several control deficiencies individually less severe than significant deficiencies. The auditor should evaluate whether to:', '["Communicate these deficiencies to management because they may warrant attention even though written governance communication is not required", "Disregard these deficiencies entirely because they do not meet the significant deficiency reporting threshold", "Include these deficiencies in the formal written communication to those charged with governance", "Defer all reporting of these deficiencies until they persist for two consecutive audit periods"]'::jsonb, 0, 'Under AU-C 265.A19, the auditor may communicate control deficiencies that are less severe than significant deficiencies to management, particularly when management is unaware of them. While written governance communication is only required for significant deficiencies and material weaknesses, lesser deficiencies may still merit management''s attention. Choice B is incorrect because not meeting the significant deficiency threshold does not mean deficiencies should be ignored; they may present operational risks worthy of communication.', 'easy', 4),

-- Q30: medium / L2 — Anomalous misstatement treatment in projection (tainting)
(1, 'Misstatements and Control Deficiencies', 'During the audit of Westfield Automotive Group, the auditor selects a sample of 50 inventory items from a non-stratified population of 5,000 items valued at $3 million. The sample reveals a $400 pricing error in a routine part and a $6,000 error in a custom component that the auditor determines is anomalous and not representative of the population. The projected misstatement from sampling is:', '["$640,000 because both misstatements should be projected proportionally to the full population", "$6,400 because only the detected misstatement amounts are relevant without any population projection", "$46,000 because the anomalous error should be added directly to the projected amount of the routine error", "$40,000 because only the routine pricing error should be projected to the population while the anomalous error is treated as a separate known misstatement"]'::jsonb, 3, 'Under AU-C 530.A20, when a misstatement is anomalous and not representative of the population, the auditor may exclude it from projection but must include it as a known misstatement. The routine error projects as $400 multiplied by (5,000 / 50) = $40,000, which is the projected misstatement from sampling. Choice A is incorrect because projecting the anomalous error would overstate the likely population misstatement, since that error is unique and not representative of systemic issues.', 'medium', 2)
;

COMMIT;
